// Вход: сообщение из Telegram или тестовый вызов (webhook для автотестов).
// ДЕМО: данные клиента лежат здесь, а не в Google Sheets (в локальном n8n нет подключения к Google).
const DEMO_CLIENT = {
  Имя_Отчество: 'Ренат',
  Телефон: '77000000001',
  Категория: 'Клиент',
  Статус: 'Действующий',
  Дата_открытия_счета: '01.09.2026',
  Подписка_на_рассылку: 'Да',
};
// chat id из Telegram -> данные клиента. Кого нет в списке, бот считает демо-клиентом.
const CLIENTS = {
  // '123456789': { ...DEMO_CLIENT, Имя_Отчество: 'Другое имя' },
};
// Кому уходят уведомления о переводе на человека и об ошибках.
const MADINA_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
// Ключ тестового входа: без него вызовы webhook игнорируются.
const TEST_KEY = 'YOUR_TEST_KEY';

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.message) {
    const m = j.message;
    const chatId = String(m.chat?.id ?? '');
    out.push({ json: {
      ...(CLIENTS[chatId] || DEMO_CLIENT),
      source: 'telegram', testCase: '', chatId,
      textMessage: m.text || '',
      receivedAt: m.date ? m.date * 1000 : Date.now(),
      madinaChatId: MADINA_CHAT_ID,
    } });
  } else {
    const b = j.body || {};
    if (b.key !== TEST_KEY) continue;
    if (b.forceError) throw new Error('Тестовая ошибка: проверка обработчика ошибок (кейс ' + b.case + ')');
    out.push({ json: {
      ...DEMO_CLIENT, ...(b.client || {}),
      source: 'test', testCase: String(b.case || ''),
      chatId: 'test-' + (b.case || Date.now()),
      textMessage: b.text || '',
      receivedAt: Date.now(),
      madinaChatId: MADINA_CHAT_ID,
      ...(b.hour !== undefined ? { hourOverride: Number(b.hour) } : {}),
    } });
  }
}
return out;

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastMessageTime) staticData.lastMessageTime = {};
const chatId = $json.chatId;
const ts = Date.now();
staticData.lastMessageTime[chatId] = ts;
return { json: { ...$json, _debounceTs: ts } };

const staticData = $getWorkflowStaticData('global');
const chatId = $json.chatId;
if (staticData.lastMessageTime[chatId] !== $json._debounceTs) {
  return null;
}
return { json: $json };

